#!/usr/bin/env bash
# Requiere: gh auth login  (ejecutar dentro del repo ya subido a GitHub)
set -e
gh api repos/:owner/:repo/milestones -f title="Iteración 1: Accesos y Gestión Operativa" -f description="Autenticación, usuarios, propietarios, mascotas y citas" >/dev/null || true
gh api repos/:owner/:repo/milestones -f title="Iteración 2: Módulo Clínico" -f description="Expediente médico, controles, desparasitación, tratamientos y vacunas" >/dev/null || true
gh api repos/:owner/:repo/milestones -f title="Iteración 3: Inventario Unificado" -f description="Productos, proveedores, lotes, Kardex y stock (solo Administrador)" >/dev/null || true
gh api repos/:owner/:repo/milestones -f title="Iteración 4: Punto de Venta y Pagos" -f description="Caja, carrito, pagos QR/tarjeta/efectivo y facturación" >/dev/null || true
gh api repos/:owner/:repo/milestones -f title="Iteración 5: Reportes y Auditoría" -f description="Historial de ventas, reportes, dashboard y auditoría" >/dev/null || true
gh label create iteracion-1 --color 1d76db --force
gh label create iteracion-2 --color 0e8a16 --force
gh label create iteracion-3 --color fbca04 --force
gh label create iteracion-4 --color d93f0b --force
gh label create iteracion-5 --color 5319e7 --force
gh label create rol-adm --color b60205 --force
gh label create rol-rec --color 006b75 --force
gh label create rol-vet --color c5def5 --force
gh label create historia-usuario --color 0052cc --force
gh label create prioridad-alta --color e11d21 --force
gh label create prioridad-media --color fbca04 --force
gh label create prioridad-baja --color bfdadc --force

gh issue create --title "HU-01 Iniciar sesión" --body "Como usuario interno (administrador, recepcionista o veterinario) quiero iniciar sesión con usuario y contraseña para acceder a las funciones de mi rol.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Credenciales válidas ingresan al sistema\n- [ ] Credenciales inválidas muestran mensaje genérico\n- [ ] Contraseñas almacenadas cifradas (hash)\n- [ ] Tras 5 intentos fallidos la cuenta se bloquea temporalmente" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm,rol-rec,rol-vet" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-02 Cerrar sesión y expiración por inactividad" --body "Como usuario interno quiero cerrar sesión y que esta expire por inactividad para proteger la información.\n\n**Puntos:** 2 · **Duración:** 2 días\n\n**Criterios de aceptación**\n- [ ] Botón cerrar sesión invalida el token\n- [ ] La sesión expira tras 15 min sin actividad\n- [ ] Al expirar redirige al login" --label "historia-usuario,iteracion-1,prioridad-media,rol-adm,rol-rec,rol-vet" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-03 Gestionar usuarios internos" --body "Como administrador quiero crear, editar y desactivar usuarios internos para controlar quién usa el sistema.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Solo el administrador accede al módulo\n- [ ] No permite usuarios duplicados\n- [ ] Desactivar no elimina el registro\n- [ ] Debe asignar un rol al crear" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-04 Asignar roles y permisos" --body "Como administrador quiero asignar roles (Administrador, Recepcionista, Veterinario) con permisos por módulo para limitar el acceso de cada persona.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Cada rol solo ve sus módulos en el menú\n- [ ] Acceso por URL a módulos no permitidos devuelve 403\n- [ ] Inventario y reportes solo visibles para Administrador\n- [ ] Cambios de rol quedan en auditoría" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-05 Registrar propietario" --body "Como recepcionista quiero registrar propietarios para gestionar sus mascotas y atenciones.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Nombre completo, teléfono y dirección obligatorios\n- [ ] No permite datos incompletos\n- [ ] Muestra confirmación" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm,rol-rec" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-06 Modificar propietario" --body "Como recepcionista quiero modificar los datos del propietario para mantenerlos actualizados.\n\n**Puntos:** 2 · **Duración:** 2 días\n\n**Criterios de aceptación**\n- [ ] Muestra datos actuales\n- [ ] Valida campos obligatorios\n- [ ] Confirma la actualización" --label "historia-usuario,iteracion-1,prioridad-media,rol-adm,rol-rec" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-07 Consultar propietarios" --body "Como recepcionista o veterinario quiero buscar propietarios para verificar sus datos rápidamente.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Lista nombre, teléfono y dirección\n- [ ] Búsqueda por nombre o teléfono\n- [ ] Mensaje si no hay resultados" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm,rol-rec,rol-vet" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-08 Registrar mascota" --body "Como recepcionista quiero registrar mascotas asociadas a un propietario para llevar su información de atención.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Nombre, especie, raza y edad/fecha de nacimiento\n- [ ] Debe seleccionar un propietario\n- [ ] Queda asociada al propietario" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm,rol-rec" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-09 Modificar mascota" --body "Como recepcionista quiero modificar los datos de una mascota para mantenerlos al día.\n\n**Puntos:** 2 · **Duración:** 2 días\n\n**Criterios de aceptación**\n- [ ] Muestra datos actuales\n- [ ] Valida obligatorios\n- [ ] Confirma cambios" --label "historia-usuario,iteracion-1,prioridad-media,rol-adm,rol-rec" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-10 Consultar mascotas" --body "Como recepcionista o veterinario quiero consultar mascotas y su propietario para conocer sus datos.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Lista nombre, especie, raza y propietario\n- [ ] Búsqueda por nombre\n- [ ] Mensaje si no hay resultados" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm,rol-rec,rol-vet" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-11 Registrar cita veterinaria" --body "Como recepcionista quiero registrar citas para que la mascota reciba atención en una fecha determinada.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Mascota, fecha, hora y motivo obligatorios\n- [ ] No permite dos citas del mismo veterinario a la misma hora\n- [ ] Confirma la cita" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm,rol-rec" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-12 Modificar o cancelar cita" --body "Como recepcionista quiero reprogramar o cancelar citas para mantener la agenda actualizada.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Permite cambiar fecha y hora\n- [ ] Cancelar pide confirmación\n- [ ] La cita cancelada se conserva con estado" --label "historia-usuario,iteracion-1,prioridad-media,rol-adm,rol-rec" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-13 Consultar agenda de citas" --body "Como veterinario o recepcionista quiero ver las citas programadas para conocer las próximas atenciones.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Ordenadas por fecha\n- [ ] Muestra mascota y motivo\n- [ ] Diferencia las canceladas\n- [ ] El veterinario ve por defecto su propia agenda" --label "historia-usuario,iteracion-1,prioridad-alta,rol-adm,rol-rec,rol-vet" --milestone "Iteración 1: Accesos y Gestión Operativa"
gh issue create --title "HU-14 Registrar atención en historial clínico" --body "Como veterinario quiero registrar la atención de una mascota para mantener su historial clínico.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Fecha, diagnóstico y observaciones obligatorios\n- [ ] Queda asociada a la mascota y al veterinario\n- [ ] Confirma el registro" --label "historia-usuario,iteracion-2,prioridad-alta,rol-vet,rol-adm" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-15 Consultar historial clínico" --body "Como veterinario quiero ver el historial completo de una mascota (atenciones, tratamientos, controles y vacunas) para conocer sus antecedentes.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Ordenado por fecha descendente\n- [ ] Incluye tratamientos asociados a cada atención\n- [ ] El recepcionista NO accede a diagnósticos" --label "historia-usuario,iteracion-2,prioridad-alta,rol-vet,rol-adm" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-16 Registrar control médico" --body "Como veterinario quiero registrar peso y estado de salud para dar seguimiento a la evolución.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Peso, fecha y estado obligatorios\n- [ ] Valida peso > 0\n- [ ] Asociado a la mascota" --label "historia-usuario,iteracion-2,prioridad-media,rol-vet" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-17 Consultar controles médicos" --body "Como veterinario quiero ver controles anteriores para conocer la evolución del peso y salud.\n\n**Puntos:** 2 · **Duración:** 2 días\n\n**Criterios de aceptación**\n- [ ] Lista fecha, peso y estado\n- [ ] Orden cronológico" --label "historia-usuario,iteracion-2,prioridad-media,rol-vet,rol-adm" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-18 Registrar desparasitación" --body "Como veterinario quiero registrar la desparasitación y el producto usado para mantener el control sanitario.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Fecha, producto y dosis obligatorios\n- [ ] Calcula próxima fecha sugerida\n- [ ] Confirma registro" --label "historia-usuario,iteracion-2,prioridad-media,rol-vet" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-19 Alertas de próxima desparasitación" --body "Como recepcionista quiero ver las desparasitaciones próximas a vencer para avisar al propietario.\n\n**Puntos:** 2 · **Duración:** 2 días\n\n**Criterios de aceptación**\n- [ ] Resalta fechas dentro de los próximos 7 días\n- [ ] Muestra mascota y teléfono del propietario" --label "historia-usuario,iteracion-2,prioridad-media,rol-rec,rol-vet,rol-adm" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-20 Registrar tratamientos y medicamentos" --body "Como veterinario quiero registrar tratamientos y medicamentos indicados, asociados a la atención, para dejar constancia clínica.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Tratamiento e indicaciones obligatorios\n- [ ] Se asocia automáticamente al historial clínico\n- [ ] Medicamento se elige del catálogo de inventario" --label "historia-usuario,iteracion-2,prioridad-alta,rol-vet" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-21 Consultar tratamientos de una mascota" --body "Como veterinario quiero ver los tratamientos asignados a una mascota para saber cuáles tiene o tuvo.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Muestra tratamiento, medicamento e indicaciones\n- [ ] Filtro por mascota y fechas" --label "historia-usuario,iteracion-2,prioridad-alta,rol-vet,rol-adm" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-22 Registrar y consultar vacunas" --body "Como veterinario quiero registrar y consultar las vacunas aplicadas para mantener el esquema de vacunación.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Nombre de vacuna, fecha y lote\n- [ ] Mensaje si no existen vacunas\n- [ ] Recepcionista solo lectura" --label "historia-usuario,iteracion-2,prioridad-media,rol-vet,rol-rec,rol-adm" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-23 Recordatorio de próxima vacuna" --body "Como recepcionista quiero ver las vacunas por renovar para contactar a los propietarios.\n\n**Puntos:** 2 · **Duración:** 2 días\n\n**Criterios de aceptación**\n- [ ] Lista vacunas a vencer en 15 días\n- [ ] Muestra datos de contacto" --label "historia-usuario,iteracion-2,prioridad-baja,rol-rec,rol-vet,rol-adm" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-24 Exportar carnet de vacunación en PDF" --body "Como veterinario quiero exportar el carnet de vacunación para entregarlo al propietario.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] PDF con datos de mascota, propietario y vacunas\n- [ ] Incluye fecha de emisión" --label "historia-usuario,iteracion-2,prioridad-baja,rol-vet,rol-rec,rol-adm" --milestone "Iteración 2: Módulo Clínico"
gh issue create --title "HU-25 Registrar categorías y marcas" --body "Como administrador quiero registrar categorías y marcas para organizar el catálogo.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Nombre obligatorio y único\n- [ ] Lista de registrados\n- [ ] Solo administrador" --label "historia-usuario,iteracion-3,prioridad-alta,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-26 Dar de alta productos" --body "Como administrador quiero dar de alta productos con código de barras, categoría, marca, precio y stock inicial para tener catálogo completo.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Campos obligatorios validados\n- [ ] Código de barras único\n- [ ] Stock inicial genera movimiento en Kardex" --label "historia-usuario,iteracion-3,prioridad-alta,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-27 Modificar y desactivar productos" --body "Como administrador quiero modificar o desactivar productos para mantener precios vigentes.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Edita nombre, precio, categoría y marca\n- [ ] Producto desactivado no aparece en venta\n- [ ] Cambios de precio auditados" --label "historia-usuario,iteracion-3,prioridad-media,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-28 Registrar proveedores" --body "Como administrador quiero registrar proveedores para saber a quién se compra cada producto.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Nombre, NIT y teléfono\n- [ ] NIT único\n- [ ] Lista de proveedores" --label "historia-usuario,iteracion-3,prioridad-alta,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-29 Registrar entradas por orden de compra" --body "Como administrador quiero registrar órdenes de compra para aumentar el stock al recibir mercadería.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Selecciona proveedor y productos con cantidad y costo\n- [ ] Al confirmar aumenta stock\n- [ ] Registra movimiento en Kardex" --label "historia-usuario,iteracion-3,prioridad-alta,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-30 Registrar salidas y ajustes de inventario" --body "Como administrador quiero registrar mermas, daños o ajustes para corregir diferencias.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Motivo obligatorio\n- [ ] No permite stock negativo\n- [ ] Queda en Kardex y auditoría" --label "historia-usuario,iteracion-3,prioridad-media,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-31 Consultar inventario y stock" --body "Como administrador quiero consultar el inventario con stock actual para decidir reposiciones.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Muestra nombre, categoría, precio, stock y estado\n- [ ] Búsqueda por nombre o código y filtro por categoría\n- [ ] Módulo oculto para otros roles" --label "historia-usuario,iteracion-3,prioridad-alta,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-32 Configurar alertas de stock mínimo" --body "Como administrador quiero definir stock mínimo por producto para reponer a tiempo.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Stock mínimo editable por producto\n- [ ] Resalta productos en o bajo el mínimo\n- [ ] Lista de reposición" --label "historia-usuario,iteracion-3,prioridad-alta,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-33 Control de lotes y vencimientos" --body "Como administrador quiero registrar lote y vencimiento al ingresar productos para evitar usar o vender caducados.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Lote y vencimiento obligatorios en medicamentos e insumos\n- [ ] Amarillo a 30 días, rojo si vencido\n- [ ] Bloquea venta y uso de lotes vencidos" --label "historia-usuario,iteracion-3,prioridad-alta,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-34 Consultar Kardex" --body "Como administrador quiero consultar el Kardex por producto y fechas para trazar cada movimiento.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Muestra entrada, salida, saldo, motivo y usuario\n- [ ] Filtro por producto y rango de fechas" --label "historia-usuario,iteracion-3,prioridad-media,rol-adm" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-35 Descuento automático de stock por atención" --body "Como veterinario quiero que al registrar una atención los insumos se descuenten del inventario para evitar doble registro.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Stock disminuye al guardar (transacción)\n- [ ] Alerta si el stock es insuficiente antes de confirmar\n- [ ] Genera orden de cobro pendiente en caja\n- [ ] El veterinario no ve costos ni gestiona inventario" --label "historia-usuario,iteracion-3,prioridad-alta,rol-vet" --milestone "Iteración 3: Inventario Unificado"
gh issue create --title "HU-36 Apertura de caja" --body "Como recepcionista (cajero) quiero abrir la caja con saldo inicial para empezar a vender.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Registra saldo inicial, usuario y hora\n- [ ] No permite vender sin caja abierta\n- [ ] Una sola caja abierta por cajero" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-37 Cierre de caja" --body "Como recepcionista quiero cerrar la caja contando el efectivo para controlar diferencias.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Muestra total esperado y contado\n- [ ] Registra la diferencia\n- [ ] Bloquea ventas tras el cierre" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-38 Carrito de venta rápido y Cliente Varios" --body "Como recepcionista quiero escanear o buscar productos y agregarlos al carrito, incluso para un Cliente Varios, para vender rápido.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Agrega por código de barras o nombre\n- [ ] Modifica cantidad y elimina ítems\n- [ ] Valida cantidad contra stock\n- [ ] Permite Cliente Varios sin propietario ni mascota\n- [ ] Calcula subtotal y total" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-39 Consultar catálogo en caja" --body "Como recepcionista quiero ver precio y stock de productos dentro del POS para informar al cliente, sin acceder al módulo de inventario.\n\n**Puntos:** 2 · **Duración:** 2 días\n\n**Criterios de aceptación**\n- [ ] Solo lectura: nombre, precio y stock\n- [ ] No muestra costos ni proveedores" --label "historia-usuario,iteracion-4,prioridad-media,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-40 Cargar atenciones pendientes al carrito" --body "Como recepcionista quiero importar atenciones clínicas pendientes de cobro al carrito para cobrar todo en una transacción.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Lista atenciones pendientes del día\n- [ ] Carga servicio e insumos al carrito\n- [ ] Permite agregar productos de tienda\n- [ ] Marca la atención como Pagada al cobrar" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-41 Pago en efectivo" --body "Como recepcionista quiero registrar pagos en efectivo con cálculo de cambio para cobrar sin errores.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Monto recibido no menor al total\n- [ ] Calcula y muestra cambio\n- [ ] Registra el pago en la caja abierta" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-42 Pago con QR" --body "Como recepcionista quiero generar un QR con el monto exacto para que el cliente pague desde su banca móvil.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] QR único con monto e ID de transacción\n- [ ] Confirma pago y cierra la venta\n- [ ] Expiración con temporizador y reintento" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-43 Pago con tarjeta" --body "Como recepcionista quiero cobrar con tarjeta débito o crédito para aceptar este medio de pago.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Envía monto exacto\n- [ ] Registra número de autorización\n- [ ] Rechazo permite reintentar o cambiar de método" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-44 Pagos mixtos" --body "Como recepcionista quiero combinar efectivo con QR o tarjeta para que el cliente pague de varias formas.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] La suma de pagos iguala el total\n- [ ] Muestra saldo pendiente\n- [ ] Cada pago se registra por separado" --label "historia-usuario,iteracion-4,prioridad-media,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-45 Emitir ticket de venta" --body "Como recepcionista quiero emitir un ticket con número correlativo único como constancia de compra.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Incluye detalle, total, método de pago y fecha\n- [ ] Correlativo único\n- [ ] Permite reimprimir" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-46 Emitir factura electrónica" --body "Como recepcionista quiero emitir factura con NIT/CI y razón social conforme a normativa tributaria.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Busca o registra NIT rápidamente\n- [ ] Valida formato de NIT/CI\n- [ ] Factura almacenada y reimprimible o enviable por correo" --label "historia-usuario,iteracion-4,prioridad-alta,rol-rec,rol-adm" --milestone "Iteración 4: Punto de Venta y Pagos"
gh issue create --title "HU-47 Consultar historial de ventas" --body "Como recepcionista o administrador quiero consultar ventas realizadas para revisarlas.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Recepcionista ve solo sus ventas; administrador todas\n- [ ] Filtro por fecha y cajero\n- [ ] Ver detalle de venta" --label "historia-usuario,iteracion-5,prioridad-media,rol-rec,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
gh issue create --title "HU-48 Anular venta con devolución de stock" --body "Como administrador quiero anular ventas restituyendo el stock para corregir errores sin perder trazabilidad.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Solo administrador\n- [ ] Motivo obligatorio\n- [ ] Restituye stock y registra Kardex\n- [ ] La venta se conserva marcada como anulada" --label "historia-usuario,iteracion-5,prioridad-media,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
gh issue create --title "HU-49 Reporte de arqueo y cierre de caja" --body "Como administrador quiero el reporte diario de arqueo para conciliar ingresos.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Saldo inicial, ingresos y saldo final\n- [ ] Totales por método de pago\n- [ ] Diferencia de arqueo y filtro por rango de fechas" --label "historia-usuario,iteracion-5,prioridad-alta,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
gh issue create --title "HU-50 Reporte de atenciones realizadas" --body "Como administrador quiero un reporte de atenciones para revisar la actividad clínica.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Fecha, mascota, veterinario y total\n- [ ] Filtro por rango de fechas\n- [ ] Cantidad total de atenciones" --label "historia-usuario,iteracion-5,prioridad-media,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
gh issue create --title "HU-51 Reporte de productos más vendidos y rotación" --body "Como administrador quiero conocer los productos más vendidos y su rotación para decidir reposiciones.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Ranking por cantidad\n- [ ] Rotación por periodo y categoría\n- [ ] Filtro por rango de fechas" --label "historia-usuario,iteracion-5,prioridad-media,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
gh issue create --title "HU-52 Reporte de inventario valorado y bajas" --body "Como administrador quiero ver el valor del inventario y bajas por vencimiento para conocer pérdidas.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Valor por producto y total\n- [ ] Lista vencidos y próximos a vencer\n- [ ] Baja por vencimiento descuenta stock" --label "historia-usuario,iteracion-5,prioridad-alta,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
gh issue create --title "HU-53 Dashboard de ingresos clínica vs tienda" --body "Como administrador quiero un dashboard con ingresos separados de clínica y tienda para ver el desempeño de un vistazo.\n\n**Puntos:** 5 · **Duración:** 5 días\n\n**Criterios de aceptación**\n- [ ] Ingresos de clínica y tienda por separado\n- [ ] Gráficos filtrables por periodo\n- [ ] Refleja datos reales" --label "historia-usuario,iteracion-5,prioridad-media,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
gh issue create --title "HU-54 Exportar reportes a PDF y Excel" --body "Como administrador quiero exportar los reportes para compartirlos o archivarlos.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Exporta PDF y XLSX\n- [ ] Respeta los filtros aplicados" --label "historia-usuario,iteracion-5,prioridad-baja,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
gh issue create --title "HU-55 Auditoría de acciones de usuarios" --body "Como administrador quiero consultar la auditoría para garantizar seguridad y trazabilidad.\n\n**Puntos:** 3 · **Duración:** 3 días\n\n**Criterios de aceptación**\n- [ ] Registra usuario, acción, fecha y hora\n- [ ] Cubre ventas anuladas, ajustes de stock y cambios de rol\n- [ ] Registros inmutables con filtros" --label "historia-usuario,iteracion-5,prioridad-alta,rol-adm" --milestone "Iteración 5: Reportes y Auditoría"
